/* v34.64 (cw-partyalign): the 90 percent party card centred its content both ways, so the title sat on the left edge in the middle of the card and the body floated 300px to its right. Content now starts at the top left under the title, one left edge like the shop. */
#root #partymodal.ui-win:not(#zz1):not(#zz2){ align-items:flex-start; justify-content:flex-start; }

check:
{v:'VER',what:'the party window content shares one left edge and starts in the top half of the card: the title and the first line start at the same left, the title is in the top third',
 run:function(){
   if(typeof openParty!=='function') return 'SKIP: no party window';
   var pm, h, s, a, b, c;
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     openParty();
     pm=document.getElementById('partymodal'); h=pm.querySelector('h3'); s=pm.querySelector('.msub');
     if(!h||!s) return 'SKIP: no party title or line';
     a=h.getBoundingClientRect(); b=s.getBoundingClientRect(); c=pm.getBoundingClientRect();
     if(Math.abs(a.left-b.left)>3) return 'the party title starts at '+Math.round(a.left)+' and its first line at '+Math.round(b.left)+', not one left edge';
     if(a.top>c.top+c.height/3) return 'the party title sits at '+Math.round(a.top-c.top)+' px down a '+Math.round(c.height)+' px card, not in the top third';
     return null;
   } finally {
     try{ __topClear(); }catch(_e){}
   } }},
